from __future__ import annotations

import json
from dataclasses import replace

import pytest

import llm_router
from tests.llm_router.support.fault_server import ScriptedHTTPServer, ScriptedResponse
from tests.llm_router.support.workers.retry import openai_chat_path

pytestmark = pytest.mark.verification_kind("unit")


def multiply(a: int, b: int) -> int:
    """Multiply two integers."""
    return a * b


def _tool_call_body() -> bytes:
    payload = {
        "id": "chatcmpl-local-tool",
        "object": "chat.completion",
        "created": 0,
        "model": "local-model",
        "choices": [
            {
                "index": 0,
                "message": {
                    "role": "assistant",
                    "content": "Let me multiply those.",
                    "tool_calls": [
                        {
                            "id": "call_multiply_1",
                            "type": "function",
                            "function": {
                                "name": "multiply",
                                "arguments": json.dumps({"a": 6, "b": 7}),
                            },
                        }
                    ],
                },
                "finish_reason": "tool_calls",
            }
        ],
        "usage": {"prompt_tokens": 20, "completion_tokens": 6, "total_tokens": 26},
    }
    return json.dumps(payload).encode("utf-8")


def _point_openrouter_at(base_url: str) -> None:
    config = llm_router.get_config()
    base_urls = dict(config.catalog.provider_base_urls)
    base_urls[llm_router.Provider.OPENROUTER] = f"{base_url}/v1"
    catalog = replace(config.catalog, provider_base_urls=base_urls)
    llm_router.install_config(replace(config, catalog=catalog))


@pytest.mark.verifies("REQ_RESPONSE_NORMALIZATION[revision==1]")
def test_round_limit_reply_exposes_normalized_public_tool_calls(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    monkeypatch.setenv("OPENROUTER_API_KEY_1", "local-openrouter-value")
    replies = [
        ScriptedResponse(
            status_code=200,
            headers={"Content-Type": "application/json"},
            body=_tool_call_body(),
        )
        for _ in range(3)
    ]
    with ScriptedHTTPServer(
        port=0,
        routes={("POST", openai_chat_path()): replies},
    ) as server:
        _point_openrouter_at(server.base_url)
        router = llm_router.LLMRouter(
            llm_router.RouterProfile(
                model=llm_router.Model.DEEPSEEK_V3,
                provider=llm_router.Provider.OPENROUTER,
            ),
        )
        response = router.query(
            "Multiply six by seven.",
            tools=[multiply],
            max_tool_rounds=1,
        )

    assert response.output_text == ""
    assert response.tool_calls == [
        llm_router.ToolCall(
            id="call_multiply_1",
            name="multiply",
            args={"a": 6, "b": 7},
            raw_arguments=json.dumps({"a": 6, "b": 7}),
        )
    ]
    assert all(type(call) is llm_router.ToolCall for call in response.tool_calls)
    assert [step.tool_name for step in response.tool_trace] == ["multiply"]
    assert next(iter(response.tool_trace)).result == 42
